<template><div ref="root" class="pa-search"><BioNexusFormField :label="label" :field-id="id" :error="error" :required="required"><div class="pa-control"><input :id="id" ref="input" :value="modelValue" class="bio-nexus-field" :maxlength="maxlength" autocomplete="off" @input="onInput" @focus="reopen" @blur="emit('blur')" @keydown.down.prevent="move(1)" @keydown.up.prevent="move(-1)" @keydown.enter.prevent="selectActive" @keydown.esc="close"/><span v-if="loading">Buscando...</span></div></BioNexusFormField><div v-if="open" class="pa-results" role="listbox"><button v-for="(row,index) in rows" :key="row.id" type="button" :class="{active:index===active}" @mousedown.prevent="select(row)"><strong>{{row.name}}</strong><small>{{patientDocument(row)}} · {{row.phone||'Sin teléfono'}}</small></button><p v-if="errorMessage" class="pa-error">{{ errorMessage }}</p><p v-else-if="!loading&&!rows.length">Sin coincidencias. Puede registrar un paciente nuevo.</p></div></div></template><script setup>import{nextTick,onBeforeUnmount,onMounted,ref}from"vue";import BioNexusFormField from"@/components/ui/BioNexusFormField.vue";import{searchAdmissionPatients}from"@/services/patientAdmissionService";const props=defineProps({modelValue:{type:String,default:""},label:{type:String,required:true},id:{type:String,required:true},error:{type:String,default:""},required:{type:Boolean,default:false},maxlength:{type:Number,default:100}}),emit=defineEmits(["update:modelValue","select","blur"]),root=ref(null),input=ref(null),rows=ref([]),loading=ref(false),open=ref(false),active=ref(-1),errorMessage=ref("");let timer=null,requestId=0;function onInput(e){const value=e.target.value;emit("update:modelValue",value);if(timer)clearTimeout(timer);requestId++;rows.value=[];errorMessage.value="";active.value=-1;if(value.trim().length<2){loading.value=false;open.value=false;return}open.value=true;timer=setTimeout(()=>search(value.trim()),280)}async function search(term){const id=++requestId;loading.value=true;errorMessage.value="";try{const result=await searchAdmissionPatients(term);if(id!==requestId)return;rows.value=Array.isArray(result)?result:[];open.value=true}catch(error){if(id!==requestId)return;rows.value=[];open.value=true;const status=Number(error?.status||error?.response?.status||0);errorMessage.value=status===404?"El Backend de Bio Nexus no tiene disponible la busqueda de pacientes.":"No fue posible buscar pacientes. Verifique que el Backend de Bio Nexus este iniciado."}finally{if(id===requestId)loading.value=false}}function select(row){emit("select",row);open.value=false}function move(step){if(!rows.value.length)return;open.value=true;active.value=(active.value+step+rows.value.length)%rows.value.length}function selectActive(){if(open.value&&active.value>=0)select(rows.value[active.value])}function reopen(){if(rows.value.length)open.value=true}function close(){open.value=false}function outside(e){if(!root.value?.contains(e.target))close()}function patientDocument(row){return [row.verification_code,row.document_number].filter(Boolean).join('-')||'Sin documento'}onMounted(()=>document.addEventListener("mousedown",outside));onBeforeUnmount(()=>{document.removeEventListener("mousedown",outside);if(timer)clearTimeout(timer);requestId++});defineExpose({focus:()=>nextTick(()=>input.value?.focus())});</script><style scoped>.pa-search{position:relative}.pa-control{position:relative}.pa-control span{position:absolute;right:12px;top:50%;transform:translateY(-50%);color:var(--bio-nexus-color-text-muted);font-size:12px}.pa-results{position:absolute;z-index:40;left:0;right:0;top:calc(100% + 4px);display:grid;max-height:280px;overflow:auto;padding:6px;border:1px solid var(--bio-nexus-color-border-strong);border-radius:var(--bio-nexus-radius-md);background:var(--bio-nexus-color-surface);box-shadow:0 16px 42px rgb(15 23 42 / 20%)}.pa-results button{display:grid;gap:2px;padding:10px;border:0;border-radius:var(--bio-nexus-radius-sm);background:transparent;text-align:left;cursor:pointer}.pa-results button:hover,.pa-results button.active{background:var(--bio-nexus-color-info-soft)}.pa-results small,.pa-results p{color:var(--bio-nexus-color-text-muted)}.pa-results p{margin:0;padding:10px}.pa-error{color:var(--bio-nexus-color-danger)!important}</style>